INSERT IGNORE INTO posts
  (section, slug, status, origin, title, excerpt, tag, level, author, read_minutes, image_url, image_alt, body, meta_description, focus_keyword, tags, featured, published_at, updated_at)
VALUES
('guias', 'o-que-e-mcp-servidores-mcp', 'published', 'manual', 'O que é MCP: servidores MCP explicados para quem tem site', 'MCP é o padrão que liga assistentes de IA a outras ferramentas e dados. Entenda sem jargão o que um servidor MCP faz, exemplos úteis para quem cuida de sites e os cuidados de segurança.', 'Com IA', 2, 'Equipe CriaSite', 4, '/capas/o-que-e-mcp-servidores-mcp.webp', 'Ilustração de um assistente de IA no centro ligado por linhas a um banco de dados, uma pasta e uma janela de ferramenta, como num padrão de conexão.', '[{"type":"p","text":"MCP, sigla de Model Context Protocol, é um padrão aberto para ligar assistentes de IA a outras ferramentas e a dados. Em vez de você copiar e colar, o assistente consulta a documentação, abre o navegador ou lê um banco de testes por meio de um conector. Veja o que é, exemplos para quem cuida de sites e os cuidados de segurança."},{"type":"h2","text":"Como funciona, sem jargão"},{"type":"p","text":"Pense em uma tomada padrão: qualquer aparelho que siga o padrão encaixa. O aplicativo de IA conversa com servidores MCP, e cada servidor oferece ações (consultar, criar, enviar), dados para leitura e modelos de pedido. Um servidor pode rodar no seu computador, o que se chama local, ou ser um serviço na internet, o remoto, normalmente com login."},{"type":"p","text":"O padrão foi criado pela Anthropic e publicado como padrão aberto, e é usado por ferramentas de várias empresas. A especificação fica no [site oficial do MCP](https://modelcontextprotocol.io)."},{"type":"h2","text":"Exemplos úteis para quem cria e cuida de sites"},{"type":"ul","items":["Um navegador controlado pela IA, para abrir a página, testar e tirar captura de tela.","A documentação atualizada de uma biblioteca, para ela inventar menos.","O repositório de código e a lista de tarefas do projeto.","Um banco de dados de teste.","Painéis de serviços, como hospedagem, domínio e e-mail, quando o próprio fornecedor oferece um servidor oficial.","Planilhas e documentos."]},{"type":"p","text":"Antes de instalar qualquer um, confira se o fornecedor do serviço tem um servidor oficial."},{"type":"h2","text":"Local ou remoto: qual escolher"},{"type":"p","text":"O servidor local roda no seu computador e costuma acessar arquivos e programas dele. É prático para testes, mas executa código na sua máquina, então só instale os de origem confiável. O servidor remoto é um serviço na internet: você faz login e dá permissões por conta. É mais simples de instalar, mas passa a haver uma empresa no meio, com a política de privacidade dela."},{"type":"h2","text":"Um exemplo de uso"},{"type":"p","text":"Suponha que você peça: confira se a página de contato abre sem erro e me mostre uma captura. Com um servidor de navegador ligado, o assistente abre o endereço, olha o resultado e devolve a imagem, em vez de apenas supor o que aconteceria. Sem ele, você precisaria abrir, testar e descrever o resultado por conta própria."},{"type":"h2","text":"MCP, skill e instruções"},{"type":"p","text":"As instruções são as regras do projeto. A [skill](/guias/skills-para-assistentes-de-ia) é como fazer uma tarefa. O MCP é com o que fazer: o acesso a ferramentas e dados. Os três se complementam."},{"type":"h2","text":"Cuidados de segurança"},{"type":"ul","items":["O servidor age com as permissões que você der. Comece só com leitura.","Use só servidores oficiais ou de fonte confiável, de preferência de código aberto.","Gere tokens, as chaves de acesso, com o menor acesso e o menor prazo possível.","Nunca ligue o banco de produção com permissão de escrita no começo.","O texto que volta de uma ferramenta pode trazer instruções maliciosas, a chamada injeção de prompt. Mantenha a confirmação antes de cada ação.","Desligue o que você não usa."]},{"type":"p","text":"O guia de [segurança ao criar site com IA](/guias/seguranca-ao-criar-site-com-ia) explica esses riscos com mais detalhe."},{"type":"h2","text":"Passo a passo para testar o primeiro"},{"type":"ol","items":["Confira se o seu assistente aceita MCP e onde isso é configurado.","Escolha um servidor só de leitura.","Instale seguindo a instrução oficial do servidor.","Dê o mínimo de permissão.","Peça uma tarefa simples e veja quais ações ele chamou.","Mantenha a aprovação manual de cada ação."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Ligar dezenas de servidores: eles ocupam espaço na conversa e aumentam o risco.","Usar um token de administrador.","Instalar um servidor de origem desconhecida.","Aprovar tudo automaticamente.","Esquecer um servidor ligado com acesso a dados de clientes."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Preciso de MCP para criar um site?"},{"type":"p","text":"Não. Ele ajuda em tarefas específicas, mas dá para criar um site sem ele."},{"type":"h3","text":"MCP é pago?"},{"type":"p","text":"O padrão é aberto. Os servidores e os serviços por trás deles podem cobrar."},{"type":"h3","text":"MCP é de uma empresa só?"},{"type":"p","text":"Não. É um padrão aberto e usado por várias empresas."},{"type":"h3","text":"Posso criar o meu próprio servidor?"},{"type":"p","text":"Pode, com os kits oficiais, mas isso exige programação."},{"type":"p","text":"Este é o fim do [roteiro](/criar-site-com-ia#alem). Se o site ainda não está no ar, siga a [trilha do domínio ao primeiro visitante](/trilha)."},{"type":"p","text":"Leia também: [Arquivo de instruções para IA: o que dizer ao assistente de código](/guias/arquivo-de-instrucoes-para-assistente-de-codigo)"}]', 'MCP é o padrão aberto que liga assistentes de IA a ferramentas e dados. Veja o que um servidor MCP faz, quando usar e os cuidados de segurança.', 'o que é mcp', '["IA","MCP","Integrações"]', 0, UTC_TIMESTAMP() - INTERVAL 47 HOUR - INTERVAL 10 MINUTE, NULL),
('guias', 'skills-para-assistentes-de-ia', 'published', 'manual', 'Skills para assistentes de IA: o que são e como criar as suas', 'Uma skill é uma receita guardada que o assistente usa quando a tarefa pede. Veja quando vale criar uma, como montar a sua e os cuidados com skills feitas por outras pessoas.', 'Com IA', 2, 'Equipe CriaSite', 4, '/capas/skills-para-assistentes-de-ia.webp', 'Ilustração de três cartões de receita lado a lado, com o do meio em laranja e levantado, representando a skill escolhida pelo assistente para a tarefa.', '[{"type":"p","text":"Uma skill é um pacote com nome, descrição e um passo a passo, às vezes com modelos e scripts, que o assistente de IA usa quando a tarefa combina com ela. Em vez de repetir o mesmo pedido longo toda vez, você guarda a receita uma vez. Veja quando vale criar uma skill, como montar a sua e os cuidados com as de terceiros."},{"type":"h2","text":"Skill, instrução e pedido"},{"type":"p","text":"São três coisas diferentes. A instrução do projeto vale sempre e traz as regras gerais, como no guia sobre [arquivo de instruções](/guias/arquivo-de-instrucoes-para-assistente-de-codigo). O pedido é o que você quer agora. A skill é um procedimento específico, carregado só quando a descrição combina com a tarefa ou quando você a chama."},{"type":"p","text":"Em outras ferramentas a mesma ideia aparece como comandos personalizados, regras ou pedidos salvos. O nome e o formato mudam: confira na documentação da sua ferramenta."},{"type":"h2","text":"Como uma skill costuma ser montada"},{"type":"p","text":"Nas ferramentas que usam pastas, uma skill é uma pasta com um arquivo principal em Markdown. No topo ficam o nome e a descrição; embaixo, as instruções. Arquivos de apoio, como modelos, exemplos e scripts, ficam na mesma pasta."},{"type":"p","text":"A descrição é o que o assistente lê para decidir se usa a skill: diga o que ela faz e quando usar. A skill pode ficar no projeto, para a equipe toda, ou na pasta do usuário, valendo para todos os seus projetos. Não copie campos exatos de um formato sem conferir a documentação."},{"type":"h2","text":"Ideias para quem cuida de sites"},{"type":"ul","items":["Publicar um post novo no padrão do site.","Revisar uma página antes de publicar.","Preparar imagens novas, com o tamanho e o formato certos.","Seguir o checklist de atualização de plugins.","Escrever o resumo das mudanças para o cliente.","Montar o relatório mensal de pendências."]},{"type":"h2","text":"Passo a passo para criar a sua"},{"type":"ol","items":["Escolha uma tarefa que se repete e que tem um jeito certo de ser feita.","Faça uma vez com o assistente, anotando as correções que você precisou pedir.","Dê um nome curto e escreva uma descrição com o que a skill faz e quando usar.","Escreva os passos no imperativo, com um critério de pronto.","Junte um modelo ou um exemplo do resultado esperado.","Teste numa tarefa real e ajuste o que falhar.","Guarde no Git junto com o projeto."]},{"type":"h2","text":"Um exemplo de skill, em palavras"},{"type":"p","text":"Imagine uma skill chamada novo-post, para um blog em HTML. A descrição diz: cria uma página de post a partir de um texto, seguindo o modelo do site; use quando o dono pedir um artigo novo. No corpo, os passos: copiar o modelo de post, preencher título, descrição e data, ajustar a imagem de capa, adicionar o link na página inicial e listar os arquivos alterados. Junto, fica o arquivo de modelo."},{"type":"p","text":"Quando você pedir um artigo novo, o assistente reconhece a descrição, carrega a receita e segue os mesmos passos de sempre, sem você repetir nada."},{"type":"h2","text":"Como saber se a skill funciona"},{"type":"p","text":"Peça a tarefa de duas formas diferentes e veja se o assistente a usa nas duas. Se ela não é chamada, a descrição está vaga ou diferente demais do jeito como você pede. Se ela é chamada em tarefas que não têm a ver, a descrição está ampla demais. Ajuste a descrição primeiro e os passos depois."},{"type":"h2","text":"Cuidados com skills de terceiros"},{"type":"p","text":"Uma skill pode incluir scripts que rodam no seu computador. Leia tudo antes de instalar e só use as de fonte confiável. Desconfie de qualquer instrução que mande enviar arquivos ou dados para fora. O guia de [segurança ao criar site com IA](/guias/seguranca-ao-criar-site-com-ia) explica os riscos."},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Escrever uma descrição vaga, e a skill nunca é usada ou é usada na hora errada.","Criar uma skill que tenta fazer tudo.","Repetir na skill as regras que já estão no arquivo de instruções.","Instalar uma skill de terceiros sem ler.","Esquecer de atualizar a skill quando o processo muda."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Skill é o mesmo que plugin?"},{"type":"p","text":"São parecidos. Em algumas ferramentas, um plugin junta skills, comandos e conexões."},{"type":"h3","text":"Preciso programar para criar uma skill?"},{"type":"p","text":"Não. A maior parte é texto. Os scripts são opcionais."},{"type":"h3","text":"Funciona em qualquer assistente?"},{"type":"p","text":"O conceito sim. O formato varia de ferramenta para ferramenta."},{"type":"h3","text":"A skill substitui o MCP?"},{"type":"p","text":"Não. A skill ensina como fazer a tarefa; o MCP dá acesso a ferramentas e dados."},{"type":"p","text":"O próximo passo é entender o [MCP](/guias/o-que-e-mcp-servidores-mcp), a outra peça desta etapa do [roteiro](/criar-site-com-ia#alem)."},{"type":"p","text":"Leia também: [Como revisar código gerado por IA: checklist antes de publicar](/guias/como-revisar-codigo-gerado-por-ia)"}]', 'Entenda o que são skills em assistentes de IA, quando valem a pena e como escrever uma skill própria para tarefas que você repete no seu site.', 'skills ia', '["IA","Skills","Automação"]', 0, UTC_TIMESTAMP() - INTERVAL 41 HOUR - INTERVAL 35 MINUTE, NULL),
('guias', 'site-feito-com-ia-seo-acessibilidade-e-velocidade', 'published', 'manual', 'Site feito com IA: como conferir SEO, acessibilidade e velocidade', 'Um site montado pela IA pode parecer pronto e ser invisível para o Google, difícil de usar com leitor de tela ou lento no celular. Veja o que conferir e como pedir as correções.', 'Com IA', 1, 'Equipe CriaSite', 4, '/capas/site-feito-com-ia-seo-acessibilidade-e-velocidade.webp', 'Ilustração do rascunho de uma página ao lado de três selos aprovados: uma lupa de busca, um círculo de contraste e um raio de velocidade.', '[{"type":"p","text":"Ferramentas de IA tendem a caprichar na aparência. O que não aparece na tela, como o código, os títulos, os rótulos dos campos e o peso das imagens, fica por sua conta. Veja o que conferir para o site ser encontrado na busca, ser usado por todas as pessoas e abrir rápido no celular, e como pedir as correções à IA."},{"type":"h2","text":"O Google consegue ler o seu site?"},{"type":"p","text":"Alguns geradores entregam páginas que montam o conteúdo no navegador com JavaScript. O Google consegue processar JavaScript, mas o caminho mais seguro é o texto principal já vir no HTML. Para testar, abra a página, aperte Ctrl+U para ver o código-fonte e procure uma frase do texto."},{"type":"p","text":"Cada página precisa de endereço próprio, título e descrição próprios (a ferramenta de [meta tags](/ferramentas/meta-tags) ajuda), um só H1 e um sitemap. A base está no guia de [SEO básico](/guias/seo-basico-para-aparecer-no-google)."},{"type":"h2","text":"Texto escrito com IA e o Google"},{"type":"p","text":"O Google diz avaliar a utilidade e a qualidade do conteúdo, e não a forma como foi produzido. Páginas feitas em massa para manipular a busca violam as regras de spam. A orientação completa fica na [documentação da Busca](https://developers.google.com/search/docs). Na prática, use os fatos do seu negócio, fotos reais e nenhum depoimento inventado."},{"type":"h2","text":"Acessibilidade"},{"type":"ul","items":["Texto alternativo que descreve cada imagem; imagem só decorativa fica com o texto alternativo vazio.","Contraste AA, de 4,5 para 1 em texto normal, conferido na [ferramenta de contraste](/ferramentas/contraste-cores).","Tudo funciona com a tecla Tab e o foco aparece na tela.","Cada campo de formulário tem um rótulo.","O idioma da página está definido como português do Brasil, pelo atributo lang com o valor pt-BR.","Os títulos seguem a ordem, sem pular de nível.","Nenhuma informação depende só da cor."]},{"type":"h2","text":"Velocidade"},{"type":"p","text":"Os problemas mais comuns em sites feitos por IA são imagens enormes, bibliotecas pesadas para algo simples, animações demais e muitas fontes. Meça no PageSpeed Insights, a ferramenta gratuita do Google, e olhe os limites de bom: LCP até 2,5 segundos, INP até 200 milissegundos e CLS até 0,1. Reduza o peso das imagens antes de publicar."},{"type":"h2","text":"Um teste de cinco minutos"},{"type":"ol","items":["Abra o site no celular, com os dados móveis, e veja quanto tempo leva para aparecer o conteúdo.","Aperte a tecla Tab várias vezes e observe se o foco passa por todos os links e botões, na ordem certa.","Amplie o texto do navegador e veja se nada se sobrepõe.","Procure no código-fonte uma frase do texto principal.","Abra duas páginas internas e confira se cada uma tem um título diferente na aba do navegador."]},{"type":"p","text":"Esse teste não substitui uma auditoria, mas pega os problemas mais comuns em poucos minutos e mostra o que pedir à IA."},{"type":"h2","text":"Formulários e contato"},{"type":"p","text":"Geradores costumam criar formulários que parecem funcionar e não enviam nada. Preencha o formulário com os seus próprios dados e confira se a mensagem chegou ao e-mail ou ao WhatsApp do negócio. Confira também a mensagem de erro: ela deve dizer o que corrigir, e não apenas ficar em vermelho."},{"type":"h2","text":"Como pedir as correções"},{"type":"ol","items":["Meça o site antes de mexer.","Cole o resultado no pedido.","Peça uma correção por vez.","Meça de novo.","Registre a regra no arquivo de instruções, por exemplo: toda imagem tem texto alternativo. Assim a IA não repete o erro."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Publicar o texto de exemplo que veio junto com o modelo.","Colocar tudo em uma página só, e fica difícil aparecer na busca por cada serviço.","Fazer um menu que só abre com o mouse.","Escrever um texto alternativo enorme em imagem decorativa.","Deixar páginas sem título próprio.","Confiar na nota que a própria ferramenta de IA dá ao site."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Site feito com IA é penalizado?"},{"type":"p","text":"Não por ser feito com IA. O que conta é a qualidade e a utilidade da página."},{"type":"h3","text":"Preciso de nota 100?"},{"type":"p","text":"Não. Os limites de bom importam mais do que a nota máxima."},{"type":"h3","text":"Como saber se uma pessoa cega consegue usar o site?"},{"type":"p","text":"Teste com o teclado e com o leitor de tela do celular. Verificadores automáticos pegam só uma parte dos problemas."},{"type":"h3","text":"A IA consegue corrigir sozinha?"},{"type":"p","text":"Boa parte, se você mostrar o problema e conferir o resultado depois."},{"type":"p","text":"Falta proteger o projeto antes de publicar: veja [segurança ao criar site com IA](/guias/seguranca-ao-criar-site-com-ia) e o passo no [roteiro](/criar-site-com-ia#revisar)."},{"type":"p","text":"Leia também: [Site lento: causas e como otimizar imagens](/guias/site-lento-causas-e-como-otimizar-imagens)"}]', 'O site que a IA montou aparece no Google, abre rápido e todos conseguem usar? Veja o que conferir em títulos, código, imagens, contraste e celular.', 'site feito com ia', '["IA","SEO","Acessibilidade"]', 0, UTC_TIMESTAMP() - INTERVAL 34 HOUR - INTERVAL 5 MINUTE, NULL),
('guias', 'como-revisar-codigo-gerado-por-ia', 'published', 'manual', 'Como revisar código gerado por IA: checklist antes de publicar', 'Código gerado por IA costuma funcionar no primeiro teste e esconder problemas. Revisar não exige ser programador experiente, exige método: veja o checklist em cinco blocos.', 'Com IA', 2, 'Equipe CriaSite', 4, '/capas/como-revisar-codigo-gerado-por-ia.webp', 'Ilustração de um painel de código com linhas marcadas em verde e uma em laranja, ao lado de uma lista de revisão com dois itens concluídos.', '[{"type":"p","text":"O código que a IA escreve costuma passar no primeiro teste e esconder um caso não tratado, uma falha de segurança ou um arquivo alterado sem que você tenha pedido. Revisar não exige anos de experiência, exige método. Este guia traz um checklist em cinco blocos para usar antes de publicar qualquer coisa que a IA tenha escrito."},{"type":"h2","text":"Entenda o que mudou"},{"type":"p","text":"Comece pela lista de arquivos alterados: o Git mostra as linhas que mudaram. Peça à IA que explique, em português, cada mudança e o motivo dela. Desconfie de qualquer alteração fora do que você pediu e pergunte: o que pode dar errado com isso?"},{"type":"h2","text":"Funciona de verdade?"},{"type":"ul","items":["Gere a versão final do projeto, o build, e leia os erros e avisos que aparecerem.","Teste o caminho certo e também os errados: campo vazio, e-mail inválido, internet lenta.","No formulário, confira se a mensagem realmente chega a quem deveria.","Abra no celular e no computador.","Confira links e redirecionamentos com a ferramenta de [status HTTP](/ferramentas/status-http).","Abra o console do navegador (tecla F12) e procure erros em vermelho.","Passe o HTML pelo [validador do W3C](https://validator.w3.org)."]},{"type":"h2","text":"Segurança"},{"type":"ul","items":["Nenhuma senha ou chave no código que vai para o navegador.","Dados validados também no servidor, e não só na tela.","Consultas ao banco feitas com parâmetros, sem juntar texto do visitante.","Dependências novas conferidas uma a uma.","Área de administração protegida por senha."]},{"type":"p","text":"O guia de [segurança ao criar site com IA](/guias/seguranca-ao-criar-site-com-ia) detalha cada um desses pontos."},{"type":"h2","text":"Qualidade e manutenção"},{"type":"ul","items":["Nomes claros para arquivos, funções e variáveis.","Nada duplicado e nada de código comentado ou morto.","Textos de exemplo, depoimentos inventados e lorem ipsum removidos.","O resultado segue as regras do projeto."]},{"type":"h2","text":"Checklist rápido antes de publicar"},{"type":"ol","items":["Li a lista de arquivos alterados.","Entendi cada mudança.","O build rodou sem erro.","Testei no celular e no computador.","Testei o formulário e os links.","Nenhuma senha ou chave está no código.","Conferi as dependências novas.","Salvei a versão com uma mensagem clara.","Publiquei e conferi no ar com o [checklist de lançamento](/guias/checklist-de-lancamento-do-site)."]},{"type":"h2","text":"Peça uma revisão à própria IA, com cuidado"},{"type":"p","text":"Depois de escrever o código, vale pedir à IA que o releia como se fosse outra pessoa: quais casos não foram tratados, o que pode quebrar em um celular antigo, onde há risco de segurança. Ela costuma achar problemas reais. Trate a resposta como uma lista de pontos para investigar, e não como veredito. Teste cada item apontado antes de aceitar a correção."},{"type":"h2","text":"Quando o teste falha"},{"type":"p","text":"Se algo não funcionar, resista à vontade de repetir corrija até passar. Cole a mensagem de erro completa, diga o que você esperava e o que aconteceu, e peça uma explicação da causa antes de qualquer alteração. Se a segunda tentativa também falhar, volte à última versão salva no Git e recomece o pedido, menor e mais claro."},{"type":"h2","text":"Quando pedir ajuda a outra pessoa"},{"type":"p","text":"Há situações em que a revisão deve passar por alguém com experiência: o site recebe pagamentos, guarda dados de clientes, tem área com login ou vai ser usado por muita gente. Nesses casos, a conferência de uma pessoa da área vale mais do que qualquer checklist."},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Revisar só olhando a tela, sem ler o que mudou.","Pedir corrija em sequência sem entender o erro: a IA pode piorar e mexer em mais arquivos.","Aceitar um teste que a própria IA alterou para ele passar.","Juntar várias mudanças em um commit só, e depois não saber o que voltar.","Publicar sem tempo para corrigir se der errado."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Preciso entender cada linha?"},{"type":"p","text":"Entenda o que mudou e onde. O que você não entender, peça para a IA explicar ou não publique."},{"type":"h3","text":"Outra IA pode revisar?"},{"type":"p","text":"Ajuda como segunda opinião, mas não substitui o teste feito por você."},{"type":"h3","text":"Testes automáticos valem a pena?"},{"type":"p","text":"Em projeto que cresce, sim. Confira se eles testam algo real e não apenas passam."},{"type":"h3","text":"Por onde começar se eu não souber o que testar?"},{"type":"p","text":"Pelo que o visitante faz: abrir, ler, clicar e enviar."},{"type":"p","text":"Além de funcionar, o site precisa ser encontrado e usado por todos: veja [SEO, acessibilidade e velocidade em sites feitos com IA](/guias/site-feito-com-ia-seo-acessibilidade-e-velocidade) e o passo no [roteiro](/criar-site-com-ia#revisar)."},{"type":"p","text":"Leia também: [Prompt para criar site com IA: como pedir e o que incluir](/guias/prompt-para-criar-site-com-ia)"}]', 'Checklist para revisar o código que a IA escreveu antes de publicar: entender o que mudou, testar no celular, conferir formulários, segurança e desempenho.', 'revisar código gerado por ia', '["IA","Revisão de código","Testes"]', 0, UTC_TIMESTAMP() - INTERVAL 27 HOUR - INTERVAL 50 MINUTE, NULL),
('guias', 'arquivo-de-instrucoes-para-assistente-de-codigo', 'published', 'manual', 'Arquivo de instruções para IA: o que dizer ao assistente de código', 'O assistente não lembra das conversas anteriores. Um arquivo de instruções na pasta do projeto guarda as regras: o que colocar, o que nunca escrever nele e um modelo para começar.', 'Com IA', 2, 'Equipe CriaSite', 4, '/capas/arquivo-de-instrucoes-para-assistente-de-codigo.webp', 'Ilustração de um arquivo de texto com títulos e listas sendo lido por um assistente de IA, representado por um círculo azul-marinho com uma faísca branca.', '[{"type":"p","text":"Cada conversa com o assistente de código começa do zero. Sem regras escritas, você repete as mesmas instruções e recebe respostas diferentes a cada vez. O arquivo de instruções é um texto guardado na pasta do projeto que a ferramenta lê no começo de cada sessão. Veja o que colocar nele, o que nunca escrever e um modelo para começar."},{"type":"h2","text":"O que é e onde fica"},{"type":"p","text":"É um arquivo de texto, em geral em Markdown, um formato simples em que o símbolo de cerquilha marca um título. Ele fica na raiz do projeto. O nome depende da ferramenta: por exemplo, AGENTS.md é uma convenção aberta lida por várias ferramentas, e CLAUDE.md é lido por outras; alguns editores usam arquivos de regras em pastas próprias. Confira na documentação da sua ferramenta qual nome ela lê."},{"type":"p","text":"Algumas ferramentas aceitam também um arquivo por pasta e um arquivo pessoal que vale para todos os seus projetos. O arquivo do projeto vai para o Git e vale para quem trabalha nele; as preferências pessoais ficam no arquivo pessoal."},{"type":"h2","text":"O que colocar"},{"type":"ul","items":["O que é o projeto e para quem, em duas frases.","As tecnologias principais.","Os comandos para instalar, rodar, testar e gerar a versão de produção.","A estrutura de pastas, em poucas linhas.","As convenções: idioma dos textos, nomes, estilo e componentes que devem ser reaproveitados.","As regras de trabalho: perguntar antes de apagar arquivos, instalar dependências ou mexer no banco; rodar o build antes de dizer que terminou; não mudar o que não foi pedido.","Onde está a documentação do projeto."]},{"type":"h2","text":"O que não colocar"},{"type":"ul","items":["Senhas, chaves de API e dados de acesso. O arquivo vai para o Git e para o contexto da IA. Veja o guia de [segurança ao criar site com IA](/guias/seguranca-ao-criar-site-com-ia).","Dados pessoais de clientes.","Texto enorme: instrução demais compete por atenção. Seja curto e direto.","Regras vagas ou contraditórias, como escreva código bom.","O que a ferramenta já descobre sozinha lendo o código."]},{"type":"h2","text":"Modelo para começar"},{"type":"p","text":"Um exemplo para um site fictício de confeitaria. Adapte cada linha ao seu projeto:"},{"type":"ul","items":["Projeto: site de uma confeitaria de bairro, para clientes que encomendam bolos pelo WhatsApp.","Tecnologias: HTML, CSS e um pouco de JavaScript, sem bibliotecas.","Comandos: instalar com npm install, rodar com npm run dev, gerar a versão final com npm run build.","Textos: português do Brasil, sem jargão.","Antes de apagar arquivos ou instalar algo: pergunte.","Antes de dizer que terminou: rode o build e liste os arquivos alterados.","Nunca: escrever senha ou chave no código."]},{"type":"h2","text":"Regra boa e regra ruim"},{"type":"p","text":"Uma regra boa é específica e dá para conferir. Em vez de “escreva código de qualidade”, prefira “ao final de cada tarefa, rode o build e informe se houve erro”. Em vez de “use um tom adequado”, prefira “textos em português do Brasil, sem gírias”. Quanto mais concreta a regra, mais fácil é perceber quando ela foi descumprida e corrigir o arquivo."},{"type":"p","text":"Se o assistente erra a mesma coisa duas vezes, transforme a correção em uma linha do arquivo. Com o tempo, ele vira o registro das decisões do projeto, útil também para quem chegar depois."},{"type":"h2","text":"Quando a instrução vira skill"},{"type":"p","text":"Um procedimento longo, usado só às vezes, como publicar um post no padrão do site ou preparar imagens, fica melhor como uma receita carregada sob demanda. Isso é uma skill, tema do guia sobre [skills para assistentes de IA](/guias/skills-para-assistentes-de-ia). Em resumo: instrução vale sempre, skill é a receita de uma tarefa."},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Deixar o arquivo desatualizado, e o assistente segue regra velha.","Copiar regras genéricas da internet que não têm a ver com o projeto.","Escrever um segredo dentro do arquivo.","Fazer um arquivo gigante que ninguém mais lê.","Deixar o arquivo fora do Git.","Achar que a IA sempre obedece: a instrução orienta, mas não trava. Para o que é crítico, use as permissões da ferramenta e revise."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Funciona em qualquer assistente?"},{"type":"p","text":"A ideia vale para todos. O nome do arquivo e o lugar onde ele fica mudam de uma ferramenta para outra."},{"type":"h3","text":"Em que língua escrever?"},{"type":"p","text":"Pode ser em português. Seja claro e consistente do começo ao fim."},{"type":"h3","text":"A IA pode escrever o arquivo?"},{"type":"p","text":"Pode propor um rascunho depois de ler o projeto. Revise e corte o que for desnecessário."},{"type":"h3","text":"De quanto em quanto tempo devo revisar?"},{"type":"p","text":"Sempre que uma regra mudar ou o assistente repetir o mesmo erro."},{"type":"p","text":"Com as regras escritas, é hora de pedir: veja [como escrever um bom prompt](/guias/prompt-para-criar-site-com-ia). O passo faz parte do [roteiro](/criar-site-com-ia#contexto)."},{"type":"p","text":"Leia também: [Como criar um site com IA do jeito certo, passo a passo](/guias/criar-site-com-ia-do-jeito-certo)"}]', 'O que colocar no arquivo de instruções do projeto para o assistente de código: tecnologias, comandos, regras e limites, e o que nunca escrever nele.', 'arquivo de instruções para ia', '["IA","Assistente de código","Instruções"]', 0, UTC_TIMESTAMP() - INTERVAL 20 HOUR - INTERVAL 15 MINUTE, NULL),
('guias', 'seguranca-ao-criar-site-com-ia', 'published', 'manual', 'Segurança ao criar site com IA: o que nunca colar no chat', 'O assistente vê tudo o que você cola e, se for um agente, a pasta do projeto inteira. Veja o que nunca compartilhar, como limitar o que ele faz e o que fazer se uma chave vazar.', 'Com IA', 1, 'Equipe CriaSite', 4, '/capas/seguranca-ao-criar-site-com-ia.webp', 'Ilustração de um escudo azul-marinho com fechadura laranja, uma chave riscada dentro de um balão de conversa e um selo verde de confirmação.', '[{"type":"p","text":"O assistente de IA vê tudo o que você cola no chat. Um agente, que lê arquivos e roda comandos, vê ainda a pasta do projeto e o que os comandos devolvem. Pequenos descuidos viram senha exposta, conta invadida ou dado de cliente vazado. Veja o que nunca compartilhar, como limitar o que o agente faz e o que fazer se algo vazar."},{"type":"h2","text":"O que nunca colar no chat"},{"type":"ul","items":["Senhas de painel, hospedagem, banco de dados e e-mail.","Chaves de API e tokens de acesso.","O arquivo .env inteiro, onde ficam as variáveis secretas do projeto.","Dados pessoais de clientes, como nome, CPF, telefone e pedidos. Pela LGPD você responde por eles: use dados fictícios nos testes.","Capturas de tela que mostrem dados sensíveis."]},{"type":"p","text":"Confira também nas configurações e nos termos da ferramenta se as suas conversas podem ser usadas para treinar modelos e como desligar essa opção."},{"type":"h2","text":"Segredos fora do código"},{"type":"p","text":"Guarde segredos em variáveis de ambiente no servidor e mantenha o arquivo .env dentro do .gitignore, a lista de arquivos que o Git ignora. Repositório público nunca leva segredo: há robôs que varrem repositórios públicos atrás de chaves."},{"type":"p","text":"Se uma chave vazar, apagar o arquivo não basta. Ela continua no histórico do Git e em cópias. Revogue a chave no painel do serviço e gere outra."},{"type":"h2","text":"Limite o que o agente pode fazer"},{"type":"ul","items":["Dê acesso a uma pasta só, a do projeto.","Exija confirmação antes de rodar comandos, apagar arquivos ou instalar pacotes.","Não aprove tudo automaticamente em projeto com dados reais.","Salve uma versão no Git e faça backup antes de pedidos grandes.","Use um banco de teste, não o de produção.","As regras do [arquivo de instruções](/guias/arquivo-de-instrucoes-para-assistente-de-codigo) ajudam, mas não travam nada: o que é crítico precisa de permissão limitada.","Conexões [MCP](/guias/o-que-e-mcp-servidores-mcp) devem ter o mínimo de permissão."]},{"type":"h2","text":"Pacotes e código que funcionam, mas são inseguros"},{"type":"p","text":"A IA pode sugerir um pacote que não existe ou com nome parecido com o de um conhecido, e golpistas registram esses nomes de propósito. Antes de instalar, confira na página oficial do pacote se ele existe e se é mantido, e prefira ter poucas dependências."},{"type":"p","text":"Também há código que funciona e é inseguro: formulário validado só no navegador, consulta ao banco montada com o texto do visitante (injeção de SQL), chave secreta que vai parar no navegador e área de administração sem senha. A [OWASP](https://owasp.org), fundação sem fins lucrativos, mantém listas dos riscos mais comuns em aplicações web e com IA. Outro risco é a injeção de prompt: um texto escondido em uma página ou arquivo que dá ordens ao assistente."},{"type":"h2","text":"Antes de começar um projeto"},{"type":"ul","items":["Ative a verificação em duas etapas nas contas de hospedagem, domínio e repositório.","Crie o .gitignore antes do primeiro commit, e não depois.","Separe as contas: use uma chave de teste durante o desenvolvimento e outra, só no servidor, em produção.","Decida quem pode publicar: o acesso de produção não precisa estar no seu computador de trabalho."]},{"type":"p","text":"Esses quatro cuidados levam poucos minutos e evitam a maior parte dos acidentes em projetos pequenos."},{"type":"h2","text":"Se uma chave ou senha vazar"},{"type":"ol","items":["Revogue a chave ou troque a senha na hora.","Veja no painel do serviço se houve uso estranho.","Gere uma nova e guarde no lugar certo, como variável de ambiente ou gerenciador de senhas.","Tire o segredo do código.","Ative a verificação em duas etapas.","Se houver dados de clientes envolvidos, avalie a comunicação aos titulares e à ANPD. Consulte um profissional para isso."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Colar o .env para a IA achar um erro.","Compartilhar print do painel com a chave aparecendo.","Usar dados reais de clientes para testar.","Aprovar um comando sem ler.","Instalar o pacote sugerido sem conferir.","Deixar um repositório público com segredo no histórico."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"É seguro usar IA para programar?"},{"type":"p","text":"É, com estes cuidados e com revisão do que ela escreve."},{"type":"h3","text":"A ferramenta guarda o que eu colo?"},{"type":"p","text":"Depende da ferramenta e do plano. Leia a política de privacidade dela antes de colar qualquer coisa sensível."},{"type":"h3","text":"Repositório privado resolve?"},{"type":"p","text":"Reduz o risco, mas não elimina. Segredo não vai para o Git, nem em repositório privado."},{"type":"h3","text":"Posso usar dados reais para testar?"},{"type":"p","text":"Prefira sempre dados fictícios."},{"type":"p","text":"Com o projeto protegido, siga o [checklist de lançamento do site](/guias/checklist-de-lancamento-do-site) e marque a etapa no [roteiro](/criar-site-com-ia#publicar)."},{"type":"p","text":"Leia também: [Como revisar código gerado por IA: checklist antes de publicar](/guias/como-revisar-codigo-gerado-por-ia)"}]', 'Senhas, chaves de API e dados de clientes não vão para o chat da IA. Veja como proteger o projeto, revisar pacotes e limitar o que o agente pode fazer.', 'segurança ao criar site com ia', '["IA","Segurança","LGPD"]', 0, UTC_TIMESTAMP() - INTERVAL 13 HOUR - INTERVAL 40 MINUTE, NULL),
('guias', 'prompt-para-criar-site-com-ia', 'published', 'manual', 'Prompt para criar site com IA: como pedir e o que incluir', 'Pedido vago vira site genérico, com textos inventados. Veja as partes de um bom pedido, um modelo para copiar e como pedir ajustes sem desmanchar o que já funciona.', 'Com IA', 1, 'Equipe CriaSite', 4, '/capas/prompt-para-criar-site-com-ia.webp', 'Ilustração de uma conversa com um assistente de IA: um balão com o pedido dividido em partes marcadas em laranja e a caixa de envio logo abaixo.', '[{"type":"p","text":"A IA responde ao que você escreveu, não ao que você imaginou. Tudo o que faltar no pedido, que se chama prompt, ela preenche com o mais provável: textos genéricos, cores padrão, depoimentos que nunca existiram. Neste guia você vê as partes de um bom pedido, um modelo para copiar e adaptar e como pedir ajustes sem desmanchar o que já funciona."},{"type":"h2","text":"Por que pedido vago dá site genérico"},{"type":"p","text":"Um modelo de linguagem completa as lacunas com o padrão mais comum. Quanto mais você diz, menos ele inventa. E o que ele inventa pode causar problema: depoimento falso, número sem fonte ou prêmio que a empresa nunca ganhou é propaganda enganosa, e o cliente percebe."},{"type":"h2","text":"As partes de um bom pedido"},{"type":"ul","items":["Objetivo: a ação principal do visitante, por exemplo pedir orçamento pelo WhatsApp.","Público: quem visita o site e o que procura.","Páginas e seções: a lista do que precisa existir, na ordem.","Conteúdo real: cole os seus textos ou peça espaços marcados para você preencher. Veja como organizar em [como escrever as páginas do site](/guias/como-escrever-as-paginas-do-site).","Estilo: duas cores em hexadecimal, a fonte, o clima e o que evitar. Peça contraste AA e confira na [ferramenta de contraste](/ferramentas/contraste-cores).","Tecnologia e limites: HTML e CSS simples, ou a plataforma que você usa, onde vai hospedar e sem bibliotecas desnecessárias.","Restrições: não inventar depoimentos, números nem endereços; texto em português do Brasil; rápido no celular; acessível.","Formato da resposta: pedir que ela explique o que fez, liste os arquivos e diga o que falta."]},{"type":"h2","text":"Modelo para copiar e adaptar"},{"type":"p","text":"Troque as palavras em maiúsculas pelas informações do seu negócio. O exemplo é de uma assistência técnica de celulares fictícia:"},{"type":"ul","items":["Objetivo: levar o visitante a pedir orçamento pelo WhatsApp.","Público: moradores de NOME DO BAIRRO com celular quebrado, que acessam pelo celular.","Páginas: início, serviços, como funciona, perguntas frequentes e contato.","Estilo: azul-marinho e laranja, fonte sem serifa, clima direto e confiável, sem fotos de banco de imagens.","Tecnologia: HTML e CSS simples, sem bibliotecas, para hospedar em hospedagem compartilhada.","Não faça: inventar depoimentos, preços, prêmios ou endereço. Deixe espaços marcados em MAIÚSCULAS.","Antes de escrever código: liste os arquivos e as etapas que pretende seguir e espere o meu ok."]},{"type":"h2","text":"Um pedido ruim e um pedido bom"},{"type":"p","text":"Compare dois pedidos para o mesmo negócio. O ruim diz apenas: crie um site bonito e moderno para a minha assistência técnica. A IA vai escolher sozinha o nome das seções, as cores, os textos e até os serviços, e quase tudo vai precisar ser refeito."},{"type":"p","text":"O bom traz o objetivo, o público, as páginas, o estilo, a tecnologia e o que não fazer, como no modelo acima. Ele dá mais trabalho para escrever, mas poupa várias rodadas de correção, porque o primeiro resultado já chega perto do que você precisava."},{"type":"h2","text":"Peça em partes, não o site inteiro"},{"type":"p","text":"Primeiro peça o plano, com a lista de arquivos e etapas. Depois a estrutura e a página inicial, depois cada página, depois o formulário. Um pedido deve ser uma mudança que dá para conferir antes de seguir para a próxima."},{"type":"h2","text":"Como pedir ajustes"},{"type":"ul","items":["Diga o que está errado, onde está e como deveria ficar.","Cole a mensagem de erro inteira, sem resumir.","Peça para mudar só o necessário e não mexer no resto.","Se a conversa ficou confusa, comece outra com um resumo do projeto."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Pedir um site moderno e bonito sem nenhum detalhe.","Deixar a IA inventar os textos do negócio.","Pedir tudo num pedido só.","Colar dados de clientes ou senhas dentro do pedido.","Aceitar bibliotecas e serviços que você não pediu.","Esquecer de dizer onde o site vai ser hospedado."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"O pedido precisa ser em inglês?"},{"type":"p","text":"Não. Escreva em português; os termos técnicos podem ficar como são."},{"type":"h3","text":"Posso pedir os textos para a IA?"},{"type":"p","text":"Para um rascunho, sim. Confira os fatos e acrescente o que só você sabe sobre o negócio."},{"type":"h3","text":"Existe um prompt perfeito?"},{"type":"p","text":"Não. O bom pedido deixa pouco para adivinhar e melhora a cada resposta que você corrige."},{"type":"h3","text":"Vale pedir para a IA melhorar o meu pedido?"},{"type":"p","text":"Vale. Peça que ela faça as perguntas que faltam antes de começar a escrever código."},{"type":"p","text":"Com o código pronto, o passo seguinte é [revisar o que a IA escreveu](/guias/como-revisar-codigo-gerado-por-ia) antes de publicar. Veja onde isso entra no [roteiro](/criar-site-com-ia#pedir)."},{"type":"p","text":"Leia também: [Como criar um site com IA do jeito certo, passo a passo](/guias/criar-site-com-ia-do-jeito-certo)"}]', 'Veja como escrever um bom prompt para criar um site com IA: objetivo, público, páginas, estilo, restrições e um modelo pronto para copiar e adaptar.', 'prompt para criar site', '["IA","Prompt","Iniciante"]', 0, UTC_TIMESTAMP() - INTERVAL 7 HOUR - INTERVAL 25 MINUTE, NULL),
('guias', 'criar-site-com-ia-do-jeito-certo', 'published', 'manual', 'Como criar um site com IA do jeito certo, passo a passo', 'A IA escreve código rápido, mas quem decide é você. Veja o fluxo que evita retrabalho: planejar, dar contexto, pedir em passos pequenos, revisar, testar e versionar.', 'Com IA', 1, 'Equipe CriaSite', 5, '/capas/criar-site-com-ia-do-jeito-certo.webp', 'Ilustração de um ciclo de cinco caixas ligadas por setas dentro de uma janela de navegador: plano, pedido à IA, partes pequenas, revisão aprovada e versão salva.', '[{"type":"p","text":"Assistentes de IA escrevem código em segundos e fazem criar um site parecer fácil. O que separa um site que funciona de um que vira dor de cabeça é o método: você decide o que precisa existir, a IA executa em partes e você confere cada parte antes de seguir. Neste guia estão o fluxo em seis passos e os erros mais comuns de quem começa."},{"type":"h2","text":"O que a IA faz bem e o que continua com você"},{"type":"p","text":"A IA é boa em rascunhar uma página ou um componente, repetir tarefas parecidas, explicar uma mensagem de erro e converter ou reorganizar código. Ela escreve respostas plausíveis, e plausível não é o mesmo que correto: pode inventar uma função que não existe ou afirmar algo que não confere. Por isso a conferência é sua."},{"type":"p","text":"Também continuam com você as decisões que nenhuma ferramenta toma em seu nome: o que o site precisa ter, o registro do domínio, a hospedagem e as contas em seu nome (veja [as etapas que nenhuma IA faz por você](/trilha)), os fatos do negócio nos textos ([como escrever as páginas](/guias/como-escrever-as-paginas-do-site)) e a aprovação final do que vai ao ar."},{"type":"h2","text":"Os tipos de ferramenta"},{"type":"p","text":"Há várias categorias, e a escolha depende do seu conforto com código:"},{"type":"ul","items":["Chat no navegador: você descreve o que quer e copia os trechos que ele gera para o seu projeto.","Assistente dentro do editor de código: sugere e altera os arquivos que você está abrindo, como o GitHub Copilot e o Cursor, por exemplo.","Agente de código: lê a pasta inteira do projeto, edita vários arquivos e roda comandos, no terminal ou no editor.","Gerador de site no navegador: cria e publica um projeto a partir de uma conversa.","Assistentes de IA dentro de construtores de site e do WordPress."]},{"type":"p","text":"Nomes, recursos e preços mudam com frequência. Confira sempre na documentação oficial de cada ferramenta antes de decidir."},{"type":"h2","text":"O fluxo em 6 passos"},{"type":"ol","items":["Planeje: escreva em um parágrafo o objetivo do site, o público, as páginas e o que fica de fora.","Dê contexto: diga as tecnologias, o estilo e as regras do projeto, uma vez só, em vez de repetir em cada conversa.","Peça em partes pequenas: uma página ou uma função por vez, com critério de pronto, como mostra o guia sobre [como pedir](/guias/prompt-para-criar-site-com-ia).","Revise: leia o que mudou e peça à IA que explique o que você não entendeu.","Teste: abra no navegador e no celular, preencha o formulário de verdade e clique nos links.","Salve a versão: registre no Git e só então siga para o pedido seguinte."]},{"type":"h2","text":"Git: o botão de desfazer do projeto"},{"type":"p","text":"O [Git](https://git-scm.com) é um programa gratuito e de código aberto que registra versões do projeto. Cada commit é uma foto do projeto com uma mensagem que diz o que mudou. Antes de um pedido grande, salve; se a IA quebrar alguma coisa, você volta para a foto anterior em vez de tentar consertar no escuro."},{"type":"p","text":"Ele também mostra, linha por linha, o que foi alterado, e isso é essencial quando um agente mexe em vários arquivos de uma vez. Guarde uma cópia do projeto em um repositório remoto privado, para não depender de um único computador."},{"type":"h2","text":"Comece por um projeto pequeno"},{"type":"p","text":"Para o primeiro site com IA, escolha algo pequeno e de baixo risco: uma página de apresentação, uma página de contato com o botão do WhatsApp ou um cartão de visita digital. Assim você pratica o fluxo inteiro, do plano ao site no ar, sem depender de banco de dados nem de dados de clientes. Quando a rotina estiver confortável, aumente o tamanho do projeto aos poucos."},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Pedir um site completo de uma vez: o resultado vem genérico e difícil de conferir.","Aceitar o código sem ler nada do que mudou.","Colar senha, chave de API ou dado de cliente no chat.","Deixar a conversa ficar longa demais: o assistente perde detalhes do começo. Abra outra e cole um resumo do projeto.","Trocar de ferramenta no meio do trabalho sem anotar as decisões já tomadas.","Publicar sem testar no celular."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Preciso saber programar?"},{"type":"p","text":"Para um site simples, dá para começar sem. Entender o básico de HTML e de como um site é publicado ajuda muito na hora de revisar o que a IA entregou."},{"type":"h3","text":"O que é vibe coding?"},{"type":"p","text":"É o nome popular para criar software conversando com a IA e aceitando o código sem ler. Serve para protótipo e para testar uma ideia. Em site de cliente ou com dados de pessoas, revise tudo."},{"type":"h3","text":"A IA substitui quem faz sites?"},{"type":"p","text":"Ela acelera partes do trabalho. Decidir, revisar e responder pelo resultado continua sendo de uma pessoa, e não há como prever mais do que isso."},{"type":"h3","text":"Site feito com IA é pior no Google?"},{"type":"p","text":"O Google avalia a página e a utilidade do conteúdo, não a ferramenta que a escreveu. O que pesa é a qualidade do resultado."},{"type":"p","text":"O próximo passo é dar contexto ao assistente com um [arquivo de instruções](/guias/arquivo-de-instrucoes-para-assistente-de-codigo). Acompanhe e marque cada etapa no [roteiro completo](/criar-site-com-ia#planejar)."},{"type":"p","text":"Leia também: [Segurança ao criar site com IA: o que nunca colar no chat](/guias/seguranca-ao-criar-site-com-ia)"}]', 'Planejar, dar contexto, pedir em partes pequenas, revisar, testar e salvar versões: o fluxo para criar um site com IA sem perder o controle do projeto.', 'criar site com ia', '["IA","Criar site","Vibe coding"]', 0, UTC_TIMESTAMP() - INTERVAL 2 HOUR - INTERVAL 5 MINUTE, NULL);
